from itertools import product
def build(w, deg=3):
    C=np.cos(w*t); S=np.sin(w*t)
    cols=[];names=[]
    for i,j in product(range(deg+1),repeat=2):
        if i+j<=deg:
            m=x**i*v**j
            for nm,f in [('1',np.ones_like(t)),('C',C),('S',S)]:
                cols.append(m*f); names.append(f'x^{i}v^{j}*{nm}')
    return np.column_stack(cols),names
