def fitP(w,p):
    ph=w*t**p
    C=np.cos(ph); S=np.sin(ph)
    X=np.column_stack([np.ones_like(t),C,S,x,v,x**3,np.abs(v)*v,np.tanh(v),v*C,v*S,x*C,x*S])
    b=np.linalg.lstsq(X,dv_dt,rcond=None)[0]
    return np.mean((X@b-dv_dt)**2)/np.var(dv_dt), b
